type P<T> = Promise<T>;
type Maybe<T> = P<T | null | undefined>;

// ---------------------------------------------------------------------------
// WorkflowIntegration.node module

export type WorkflowIntegrationCallback = "RenderStart" | "RenderStop" | "ResolveQuit";

export interface WorkflowIntegrationModule {
	/** pluginId must match the id in manifest.xml. */
	InitializePromise(pluginId: string): P<boolean>;
	/** Calls on the returned object return Promises and don't block the main process. */
	GetResolvePromise(): Maybe<Resolve>;
	/** @deprecated Use InitializePromise(). */
	Initialize(pluginId: string): P<boolean>;
	/**
	 * @deprecated Use GetResolvePromise(). Calls on this object block the main process and return
	 * values directly, so `await` never yields to the event loop (no IPC or repaint until done).
	 */
	GetResolve(): Maybe<Resolve>;
	RegisterCallback(callbackName: WorkflowIntegrationCallback, callbackFunc: () => void): P<boolean>;
	DeregisterCallback(callbackName: WorkflowIntegrationCallback): P<boolean>;
	/** Call on plugin quit. */
	CleanUp(): boolean;
	/** 0 disables the timeout (default). */
	SetAPITimeout(valueInSecs: number): P<boolean>;
}

